/*
 * prog39_horner – reconstructed from the obfuscated binary.
 *
 * Behaviour (as observed from the original binary):
 *
 *   • If no argument is supplied (argc < 2)          → prints "NO_INPUT".
 *   • If only one argument is supplied (argc == 2)    → prints "EMPTY".
 *   • If more than 12 coefficients are supplied
 *     (i.e. argc > 14, because argv[0] is the program name,
 *      argv[1] is the value of x, and the rest are coefficients)
 *     → prints "OUT_OF_RANGE".
 *
 *   • The first argument (argv[1]) is interpreted as a signed
 *     decimal integer `x`.  If it cannot be parsed completely,
 *     the program prints "BAD_INPUT".
 *
 *   • Each subsequent argument (argv[2] … argv[argc‑1]) is parsed
 *     as a signed decimal integer coefficient.  If any coefficient
 *     cannot be parsed completely, the program prints "BAD_INPUT".
 *
 *   • The absolute value of `x` must be ≤ 10; otherwise the program
 *     prints "OUT_OF_RANGE".
 *
 *   • The coefficients are evaluated with Horner's method, where the
 *     first coefficient supplied is the constant term, the second is
 *     the coefficient of x, and so on:
 *
 *         result = 0;
 *         for each coefficient c in the order given:
 *             result = result * x + c;
 *
 *   • The final result is printed as a signed 64‑bit integer followed
 *     by a newline.
 *
 * The program performs no other side‑effects.
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* 1. Argument‑count checks */
    if (argc < 2) {                     /* no x supplied */
        puts("NO_INPUT");
        return 0;
    }
    if (argc == 2) {                    /* only x, no coefficients */
        puts("EMPTY");
        return 0;
    }
    if (argc > 14) {                    /* more than 12 coefficients */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 2. Parse x */
    char *endptr;
    long long x = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0') {               /* bad integer format */
        puts("BAD_INPUT");
        return 0;
    }

    /* 3. Range check for x (|x| ≤ 10) */
    if (x > 10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 4. Parse coefficients */
    int coeff_cnt = argc - 2;            /* number of coefficients (≤12) */
    long long coeffs[12];                /* safe buffer */

    for (int i = 0; i < coeff_cnt; ++i) {
        coeffs[i] = strtoll(argv[2 + i], &endptr, 10);
        if (*endptr != '\0') {           /* bad integer format */
            puts("BAD_INPUT");
            return 0;
        }
    }

    /* 5. Horner evaluation (constant term first) */
    long long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeffs[i];
    }

    /* 6. Output the result */
    printf("%lld\n", result);
    return 0;
}
